-- Morfofunción: Sangre. Reejecutable; conserva material y progreso existentes.
BEGIN;
LOCK TABLE public.flashcards, public.banco_preguntas IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE morfo_incoming ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset('[{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué tipo de tejido es la sangre?","OPCION_A":"Conjuntivo líquido","OPCION_B":"Epitelial de revestimiento","OPCION_C":"Muscular liso","OPCION_D":"Nervioso periférico","RESPUESTA_CORRECTA":"A","EXPLICACION":"Sus células y fragmentos celulares están suspendidos en una matriz extracelular líquida: el plasma.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es la matriz extracelular de la sangre?","OPCION_A":"Hemoglobina","OPCION_B":"Plasma","OPCION_C":"Médula ósea roja","OPCION_D":"Capa leucoplaquetaria","RESPUESTA_CORRECTA":"B","EXPLICACION":"El plasma rodea los elementos formes y transporta solutos y proteínas.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué conjunto contiene únicamente elementos formes de la sangre?","OPCION_A":"Albúmina, globulinas y fibrinógeno","OPCION_B":"Agua, sodio y glucosa","OPCION_C":"Eritrocitos, leucocitos y plaquetas","OPCION_D":"Bilirrubina, urea y hormonas","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los elementos formes son cuerpos delimitados por membrana; las proteínas y solutos pertenecen al plasma.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál de los elementos formes es un fragmento celular?","OPCION_A":"Monocito","OPCION_B":"Eosinófilo","OPCION_C":"Linfocito","OPCION_D":"Plaqueta","RESPUESTA_CORRECTA":"D","EXPLICACION":"Las plaquetas son fragmentos del citoplasma de megacariocitos, no células completas con núcleo.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué representa el hematócrito?","OPCION_A":"Porcentaje del volumen sanguíneo ocupado por eritrocitos","OPCION_B":"Número de leucocitos por microlitro","OPCION_C":"Masa de hemoglobina en un eritrocito","OPCION_D":"Porcentaje de proteínas del plasma","RESPUESTA_CORRECTA":"A","EXPLICACION":"Es una proporción de volumen, diferente del recuento eritrocitario y de la concentración de hemoglobina.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué contiene principalmente la capa leucoplaquetaria de sangre centrifugada?","OPCION_A":"Eritrocitos y hemoglobina libre","OPCION_B":"Leucocitos y plaquetas","OPCION_C":"Albúmina y agua exclusivamente","OPCION_D":"Fibrina y bilirrubina exclusivamente","RESPUESTA_CORRECTA":"B","EXPLICACION":"Esta delgada capa se sitúa entre el plasma y la masa de eritrocitos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es una función reguladora de la sangre?","OPCION_A":"Producir bilis en los eritrocitos","OPCION_B":"Sintetizar insulina en los leucocitos","OPCION_C":"Distribuir calor y contribuir al equilibrio del pH","OPCION_D":"Filtrar la orina en las plaquetas","RESPUESTA_CORRECTA":"C","EXPLICACION":"La sangre distribuye calor y sus amortiguadores contribuyen al equilibrio ácido-base.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"Si aumenta mucho la cantidad de eritrocitos, ¿qué propiedad de la sangre tiende a aumentar?","OPCION_A":"Transparencia óptica del plasma","OPCION_B":"Difusión libre de proteínas por el endotelio","OPCION_C":"Capacidad de las plaquetas para formar núcleos","OPCION_D":"Viscosidad","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los eritrocitos contribuyen de manera importante a la resistencia de la sangre al flujo.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"707-711"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es la proteína plasmática más abundante?","OPCION_A":"Fibrinógeno","OPCION_B":"Albúmina","OPCION_C":"Hemoglobina","OPCION_D":"Mioglobina","RESPUESTA_CORRECTA":"B","EXPLICACION":"La albúmina es la principal proteína del plasma por abundancia y contribuye a transporte y presión oncótica.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué consecuencia favorece una disminución marcada de albúmina plasmática?","OPCION_A":"Mayor síntesis de hemoglobina fetal","OPCION_B":"Aumento obligatorio del número de plaquetas","OPCION_C":"Edema por reducción de la presión oncótica","OPCION_D":"Desaparición de los antígenos ABO","RESPUESTA_CORRECTA":"C","EXPLICACION":"Al disminuir la fuerza oncótica que retiene agua en los vasos, se favorece su acumulación intersticial.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué proteína soluble se convierte en la red insoluble que estabiliza el coágulo?","OPCION_A":"Albúmina","OPCION_B":"Transferrina","OPCION_C":"Ferritina","OPCION_D":"Fibrinógeno","RESPUESTA_CORRECTA":"D","EXPLICACION":"La trombina transforma el fibrinógeno en fibrina durante la coagulación.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué fracción proteica incluye a los anticuerpos circulantes?","OPCION_A":"Inmunoglobulinas","OPCION_B":"Hemoglobinas","OPCION_C":"Apoferritinas","OPCION_D":"Fibrinas","RESPUESTA_CORRECTA":"A","EXPLICACION":"Las inmunoglobulinas participan en la defensa específica y son producidas por células plasmáticas.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cómo se obtiene el suero a partir de una muestra de sangre?","OPCION_A":"Añadiendo eritrocitos al plasma","OPCION_B":"Dejando coagular y separando el coágulo","OPCION_C":"Retirando solo los leucocitos de sangre anticoagulada","OPCION_D":"Diluyendo el plasma con agua hasta la mitad","RESPUESTA_CORRECTA":"B","EXPLICACION":"El suero es el líquido posterior a la coagulación; no debe confundirse con el plasma anticoagulado.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué órgano sintetiza la mayor parte de las proteínas plasmáticas?","OPCION_A":"Bazo","OPCION_B":"Timo","OPCION_C":"Hígado","OPCION_D":"Médula suprarrenal","RESPUESTA_CORRECTA":"C","EXPLICACION":"El hígado produce albúmina y numerosos factores de coagulación; las inmunoglobulinas son una excepción importante.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué ion es el principal catión del plasma y contribuye de forma importante a su osmolaridad?","OPCION_A":"Hierro","OPCION_B":"Cobre","OPCION_C":"Zinc","OPCION_D":"Sodio","RESPUESTA_CORRECTA":"D","EXPLICACION":"El sodio es el catión extracelular predominante; la osmolaridad depende del conjunto de partículas disueltas.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué diferencia distingue presión oncótica de osmolaridad total?","OPCION_A":"La oncótica corresponde al efecto osmótico de las proteínas","OPCION_B":"La oncótica cuenta únicamente los eritrocitos","OPCION_C":"La osmolaridad excluye todos los electrólitos","OPCION_D":"Ambas expresan únicamente el volumen de plaquetas","RESPUESTA_CORRECTA":"A","EXPLICACION":"La presión oncótica es la contribución de las proteínas al movimiento osmótico del agua; no es toda la osmolaridad plasmática.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"709-712"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es el principal sitio de hematopoyesis en el adulto?","OPCION_A":"Médula espinal","OPCION_B":"Cartílago articular","OPCION_C":"Médula ósea roja","OPCION_D":"Corteza cerebral","RESPUESTA_CORRECTA":"C","EXPLICACION":"La médula ósea roja contiene las células madre y el entorno de maduración de las células sanguíneas.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué célula origina las distintas líneas de elementos formes?","OPCION_A":"Eritrocito maduro","OPCION_B":"Plaqueta circulante","OPCION_C":"Fibroblasto dérmico","OPCION_D":"Célula madre hematopoyética","RESPUESTA_CORRECTA":"D","EXPLICACION":"La célula madre hematopoyética puede autorrenovarse y originar linajes sanguíneos especializados.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué proceso produce eritrocitos?","OPCION_A":"Eritropoyesis","OPCION_B":"Leucopoyesis","OPCION_C":"Trombopoyesis","OPCION_D":"Fibrinólisis","RESPUESTA_CORRECTA":"A","EXPLICACION":"La eritropoyesis es la producción y maduración de la línea eritroide.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué hormona estimula de manera directa la producción eritroide ante hipoxia?","OPCION_A":"Trombopoyetina","OPCION_B":"Eritropoyetina","OPCION_C":"Calcitonina","OPCION_D":"Aldosterona","RESPUESTA_CORRECTA":"B","EXPLICACION":"La eritropoyetina actúa sobre precursores eritroides de la médula ósea.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué órgano aporta la mayor parte de la eritropoyetina en el adulto?","OPCION_A":"Bazo","OPCION_B":"Timo","OPCION_C":"Riñón","OPCION_D":"Páncreas","RESPUESTA_CORRECTA":"C","EXPLICACION":"La producción renal de eritropoyetina vincula la disponibilidad de oxígeno con la eritropoyesis.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué caracteriza al reticulocito?","OPCION_A":"Leucocito con núcleo multilobulado","OPCION_B":"Megacariocito con núcleo fragmentado","OPCION_C":"Eritrocito maduro con mitocondrias funcionales","OPCION_D":"Eritrocito inmaduro con restos de ARN","RESPUESTA_CORRECTA":"D","EXPLICACION":"El reticulocito ya perdió el núcleo, pero conserva material ribosomal residual durante su maduración final.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué función comparten vitamina B12 y folato en la eritropoyesis?","OPCION_A":"Favorecer la síntesis de ADN de los precursores","OPCION_B":"Formar directamente el ion ferroso del hemo","OPCION_C":"Convertir fibrinógeno en fibrina","OPCION_D":"Destruir eritrocitos envejecidos","RESPUESTA_CORRECTA":"A","EXPLICACION":"Su deficiencia altera la división y maduración de precursores sanguíneos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"En una respuesta compensadora normal a una hemorragia, ¿qué cambio puede reflejar una médula activa?","OPCION_A":"Conversión de plaquetas en eritrocitos","OPCION_B":"Aumento de reticulocitos circulantes","OPCION_C":"Aparición de núcleo en eritrocitos maduros","OPCION_D":"Descenso obligatorio de la eritropoyetina","RESPUESTA_CORRECTA":"B","EXPLICACION":"La liberación de reticulocitos aumenta cuando se acelera la producción de eritrocitos y existen recursos adecuados.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"711-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es la forma habitual de un eritrocito humano maduro?","OPCION_A":"Esfera con núcleo multilobulado","OPCION_B":"Cilindro ciliado","OPCION_C":"Célula estrellada con dendritas","OPCION_D":"Disco bicóncavo","RESPUESTA_CORRECTA":"D","EXPLICACION":"La forma bicóncava y la flexibilidad favorecen el intercambio y el paso por vasos pequeños.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué organelos faltan en el eritrocito humano maduro?","OPCION_A":"Núcleo y mitocondrias","OPCION_B":"Solo lisosomas, con núcleo conservado","OPCION_C":"Solo ribosomas, con mitocondrias abundantes","OPCION_D":"Solo aparato de Golgi, con núcleo conservado","RESPUESTA_CORRECTA":"A","EXPLICACION":"El eritrocito maduro pierde núcleo y organelos, y obtiene energía principalmente mediante glucólisis.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué componente de la hemoglobina une directamente el oxígeno?","OPCION_A":"Cadena de albúmina plasmática","OPCION_B":"Hierro ferroso del grupo hemo","OPCION_C":"Calcio de la membrana eritrocitaria","OPCION_D":"Bilirrubina del citoplasma","RESPUESTA_CORRECTA":"B","EXPLICACION":"Cada grupo hemo posee un ion Fe2+ capaz de unir una molécula de oxígeno.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuántas moléculas de oxígeno puede unir una molécula de hemoglobina completamente saturada?","OPCION_A":"Una","OPCION_B":"Dos","OPCION_C":"Cuatro","OPCION_D":"Ocho","RESPUESTA_CORRECTA":"C","EXPLICACION":"La hemoglobina contiene cuatro grupos hemo, cada uno con capacidad para una molécula de oxígeno.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué cadenas constituyen la hemoglobina adulta predominante HbA?","OPCION_A":"Dos alfa y dos gamma","OPCION_B":"Cuatro gamma","OPCION_C":"Dos beta y dos delta","OPCION_D":"Dos alfa y dos beta","RESPUESTA_CORRECTA":"D","EXPLICACION":"La HbA contiene dos cadenas alfa y dos beta; la HbF sustituye las beta por gamma.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué distingue funcionalmente a la hemoglobina fetal de la HbA?","OPCION_A":"Mayor afinidad por el oxígeno","OPCION_B":"Incapacidad para unir oxígeno","OPCION_C":"Ausencia de grupos hemo","OPCION_D":"Presencia de hierro férrico como única forma funcional","RESPUESTA_CORRECTA":"A","EXPLICACION":"Su mayor afinidad facilita la transferencia de oxígeno de la circulación materna a la fetal.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Dónde puede unirse parte del dióxido de carbono transportado por hemoglobina?","OPCION_A":"En el sitio del hierro destinado al oxígeno","OPCION_B":"En grupos de la globina","OPCION_C":"Exclusivamente dentro de la ferritina","OPCION_D":"En las cadenas de fibrina","RESPUESTA_CORRECTA":"B","EXPLICACION":"La unión de CO2 a la globina forma carbaminohemoglobina y es distinta de la unión de oxígeno al hemo.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué ventaja funcional aporta la deformabilidad eritrocitaria?","OPCION_A":"Permite dividirse dentro de los vasos","OPCION_B":"Permite fagocitar bacterias grandes","OPCION_C":"Facilita atravesar capilares de diámetro pequeño","OPCION_D":"Evita toda destrucción de eritrocitos envejecidos","RESPUESTA_CORRECTA":"C","EXPLICACION":"La flexibilidad de membrana y citoesqueleto permite cambios reversibles de forma durante el tránsito capilar.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"712-716"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es la vida media aproximada del eritrocito humano?","OPCION_A":"120 días","OPCION_B":"24 horas","OPCION_C":"7 días","OPCION_D":"10 años","RESPUESTA_CORRECTA":"A","EXPLICACION":"El envejecimiento de la membrana limita su supervivencia a unos cuatro meses.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué células eliminan muchos eritrocitos envejecidos?","OPCION_A":"Eosinófilos exclusivamente","OPCION_B":"Macrófagos","OPCION_C":"Megacariocitos","OPCION_D":"Osteoblastos","RESPUESTA_CORRECTA":"B","EXPLICACION":"Los macrófagos esplénicos, hepáticos y medulares reciclan componentes de los eritrocitos.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué proteína transporta hierro por el plasma?","OPCION_A":"Ferritina","OPCION_B":"Fibrina","OPCION_C":"Transferrina","OPCION_D":"Rodopsina","RESPUESTA_CORRECTA":"C","EXPLICACION":"La transferrina lleva hierro circulante hacia tejidos que lo utilizan o almacenan.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué proteína almacena hierro dentro de las células?","OPCION_A":"Transferrina","OPCION_B":"Protrombina","OPCION_C":"Albúmina","OPCION_D":"Ferritina","RESPUESTA_CORRECTA":"D","EXPLICACION":"La ferritina permite almacenar hierro; su función se diferencia del transporte plasmático por transferrina.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué pigmento se forma durante la degradación del hemo y puede acumularse en la ictericia?","OPCION_A":"Bilirrubina","OPCION_B":"Melanina","OPCION_C":"Rodopsina","OPCION_D":"Hemocianina","RESPUESTA_CORRECTA":"A","EXPLICACION":"La degradación del hemo produce pigmentos biliares; la acumulación de bilirrubina puede dar coloración amarilla.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué cambio define funcionalmente a la anemia?","OPCION_A":"Aumento obligatorio de plaquetas","OPCION_B":"Disminución de la capacidad sanguínea de transportar oxígeno","OPCION_C":"Exceso de todos los leucocitos","OPCION_D":"Aumento de la viscosidad por exceso eritrocitario","RESPUESTA_CORRECTA":"B","EXPLICACION":"La anemia se relaciona con insuficiencia de eritrocitos o hemoglobina y puede tener varias causas.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué alteración puede aumentar la viscosidad sanguínea por exceso eritrocitario?","OPCION_A":"Trombocitopenia","OPCION_B":"Leucopenia","OPCION_C":"Policitemia","OPCION_D":"Hemofilia","RESPUESTA_CORRECTA":"C","EXPLICACION":"Una masa eritrocitaria elevada aumenta la resistencia al flujo; es el efecto opuesto al de una deficiencia eritrocitaria.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué alteración primaria origina la drepanocitosis?","OPCION_A":"Falta completa de fibrinógeno","OPCION_B":"Ausencia de todos los leucocitos","OPCION_C":"Exceso aislado de albúmina","OPCION_D":"Una variante estructural de la hemoglobina","RESPUESTA_CORRECTA":"D","EXPLICACION":"La hemoglobina S puede polimerizar en determinadas condiciones y deformar los eritrocitos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"715-720"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué determina el grupo ABO de un eritrocito?","OPCION_A":"Cantidad de hemoglobina fetal","OPCION_B":"Presencia o ausencia de antígenos A y B","OPCION_C":"Número de mitocondrias del eritrocito","OPCION_D":"Concentración plasmática de albúmina","RESPUESTA_CORRECTA":"B","EXPLICACION":"Los antígenos A y B de la membrana eritrocitaria definen los grupos ABO.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué combinación corresponde al grupo A?","OPCION_A":"Antígeno B y anticuerpos anti-A habituales","OPCION_B":"Antígenos A y B con anti-A y anti-B habituales","OPCION_C":"Antígeno A y anticuerpos anti-B habituales","OPCION_D":"Ausencia de A y B sin anticuerpos habituales","RESPUESTA_CORRECTA":"C","EXPLICACION":"El plasma del grupo A presenta normalmente anti-B, no anti-A contra sus propios eritrocitos.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué combinación corresponde al grupo B?","OPCION_A":"Antígeno A y anticuerpos anti-B habituales","OPCION_B":"Antígenos A y B sin antígenos Rh posibles","OPCION_C":"Ausencia de A y B con antígeno A soluble","OPCION_D":"Antígeno B y anticuerpos anti-A habituales","RESPUESTA_CORRECTA":"D","EXPLICACION":"La expresión del antígeno B se acompaña habitualmente de anticuerpos contra A.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué caracteriza al grupo AB en el sistema ABO?","OPCION_A":"Antígenos A y B y ausencia habitual de anti-A y anti-B","OPCION_B":"Solo antígeno A y presencia de anti-B","OPCION_C":"Ausencia de ambos antígenos y presencia de ambos anticuerpos","OPCION_D":"Solo antígeno B y presencia de anti-A","RESPUESTA_CORRECTA":"A","EXPLICACION":"El sistema inmunitario no genera normalmente anticuerpos ABO contra los antígenos propios A y B.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué caracteriza a los eritrocitos del grupo O en el sistema ABO?","OPCION_A":"No presentan ninguna molécula antigénica de ningún sistema","OPCION_B":"No presentan antígenos A ni B","OPCION_C":"Presentan ambos antígenos A y B","OPCION_D":"Presentan antígeno A solo durante la infancia","RESPUESTA_CORRECTA":"B","EXPLICACION":"O significa ausencia de antígenos A y B, no ausencia de todos los antígenos eritrocitarios.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cómo se llama la unión de eritrocitos en grupos mediada por anticuerpos?","OPCION_A":"Eritropoyesis","OPCION_B":"Fibrinólisis","OPCION_C":"Aglutinación","OPCION_D":"Quimiotaxis","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los anticuerpos pueden enlazar eritrocitos y formar agregados; esto difiere de la formación de fibrina.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué define habitualmente a una persona Rh positiva?","OPCION_A":"Presencia obligatoria de anti-D desde el nacimiento","OPCION_B":"Ausencia de todos los antígenos eritrocitarios","OPCION_C":"Pertenencia exclusiva al grupo AB","OPCION_D":"Presencia del antígeno D eritrocitario","RESPUESTA_CORRECTA":"D","EXPLICACION":"El antígeno D es el criterio habitual de clasificación Rh positiva o negativa.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué diferencia importante existe entre anti-D y los anticuerpos ABO habituales?","OPCION_A":"Anti-D suele requerir sensibilización previa","OPCION_B":"Anti-D está presente obligatoriamente en toda persona Rh negativa","OPCION_C":"Los anticuerpos ABO solo aparecen después de una transfusión","OPCION_D":"Anti-D es una proteína que transporta hierro","RESPUESTA_CORRECTA":"A","EXPLICACION":"La exposición a eritrocitos D positivos puede sensibilizar a una persona D negativa y generar anti-D.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"719-723"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es un granulocito?","OPCION_A":"Monocito","OPCION_B":"Linfocito B","OPCION_C":"Neutrófilo","OPCION_D":"Linfocito T","RESPUESTA_CORRECTA":"C","EXPLICACION":"Neutrófilos, eosinófilos y basófilos constituyen los granulocitos.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué pareja está formada por agranulocitos?","OPCION_A":"Neutrófilos y eosinófilos","OPCION_B":"Basófilos y neutrófilos","OPCION_C":"Eritrocitos y plaquetas","OPCION_D":"Linfocitos y monocitos","RESPUESTA_CORRECTA":"D","EXPLICACION":"La clasificación distingue linfocitos y monocitos de los tres tipos de granulocitos.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué leucocito tiene un papel destacado en la fagocitosis de bacterias?","OPCION_A":"Neutrófilo","OPCION_B":"Basófilo","OPCION_C":"Linfocito B inactivo","OPCION_D":"Eritrocito","RESPUESTA_CORRECTA":"A","EXPLICACION":"Los neutrófilos son abundantes y participan de forma importante en la respuesta antibacteriana temprana.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué leucocito se vincula especialmente con defensa contra parásitos y reacciones alérgicas?","OPCION_A":"Eritrocito","OPCION_B":"Eosinófilo","OPCION_C":"Megacariocito","OPCION_D":"Reticulocito","RESPUESTA_CORRECTA":"B","EXPLICACION":"Los eosinófilos liberan productos granulares y participan en estas respuestas; la asociación no es exclusiva.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué leucocito circulante puede diferenciarse en macrófago tisular?","OPCION_A":"Basófilo","OPCION_B":"Eritrocito","OPCION_C":"Monocito","OPCION_D":"Plaqueta","RESPUESTA_CORRECTA":"C","EXPLICACION":"Los monocitos salen de la circulación y pueden convertirse en macrófagos según el tejido y las señales locales.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué células originan las células plasmáticas productoras de anticuerpos?","OPCION_A":"Neutrófilos","OPCION_B":"Eosinófilos","OPCION_C":"Megacariocitos","OPCION_D":"Linfocitos B","RESPUESTA_CORRECTA":"D","EXPLICACION":"La diferenciación de linfocitos B activados produce células plasmáticas secretoras de inmunoglobulinas.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué significa diapédesis leucocitaria?","OPCION_A":"Paso del leucocito a través de la pared vascular","OPCION_B":"División de un eritrocito maduro","OPCION_C":"Conversión de fibrinógeno en fibrina","OPCION_D":"Unión del hierro a transferrina","RESPUESTA_CORRECTA":"A","EXPLICACION":"La diapédesis permite a los leucocitos salir de los vasos hacia los tejidos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Por qué un número elevado de leucocitos en una leucemia no implica defensa eficaz?","OPCION_A":"Todos se convierten de inmediato en anticuerpos","OPCION_B":"Muchos pueden ser inmaduros o disfuncionales","OPCION_C":"Todos carecen siempre de núcleo","OPCION_D":"La hemoglobina bloquea toda fagocitosis","RESPUESTA_CORRECTA":"B","EXPLICACION":"La función depende de la maduración y competencia celular, no solo del recuento.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"724-730"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿De qué célula proceden las plaquetas?","OPCION_A":"Eritroblasto","OPCION_B":"Monoblasto","OPCION_C":"Fibroblasto","OPCION_D":"Megacariocito","RESPUESTA_CORRECTA":"D","EXPLICACION":"Los megacariocitos liberan fragmentos citoplasmáticos que se convierten en plaquetas.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué proceso limita la pérdida de sangre tras lesión vascular?","OPCION_A":"Hemostasia","OPCION_B":"Hematopoyesis","OPCION_C":"Hemólisis","OPCION_D":"Hemodilución","RESPUESTA_CORRECTA":"A","EXPLICACION":"La hemostasia integra respuestas vasculares, plaquetarias y de coagulación.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es la secuencia general de los mecanismos hemostáticos?","OPCION_A":"Fibrinólisis, eritropoyesis y hemólisis","OPCION_B":"Espasmo vascular, tapón plaquetario y coagulación","OPCION_C":"Coagulación, síntesis de albúmina y leucopoyesis","OPCION_D":"Hemólisis, aglutinación y secreción de bilis","RESPUESTA_CORRECTA":"B","EXPLICACION":"La vasoconstricción y el tapón temprano limitan la pérdida; la fibrina estabiliza después el cierre.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué cambio de la pared lesionada facilita la adhesión de plaquetas?","OPCION_A":"Aumento de la capa intacta de prostaciclina","OPCION_B":"Desaparición de toda matriz extracelular","OPCION_C":"Exposición del colágeno subendotelial","OPCION_D":"Formación de eritrocitos nucleados","RESPUESTA_CORRECTA":"C","EXPLICACION":"La lesión expone superficies que activan mecanismos de adhesión plaquetaria.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué sustancia liberada por plaquetas ayuda a reclutar más plaquetas?","OPCION_A":"Bilirrubina","OPCION_B":"Ferritina","OPCION_C":"Eritropoyetina","OPCION_D":"ADP","RESPUESTA_CORRECTA":"D","EXPLICACION":"El ADP actúa como señal amplificadora durante la activación y agregación plaquetarias.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué efecto tiene la prostaciclina del endotelio sano sobre las plaquetas?","OPCION_A":"Dificulta su activación y agregación","OPCION_B":"Convierte plaquetas en megacariocitos","OPCION_C":"Transforma directamente fibrinógeno en fibrina","OPCION_D":"Estimula la producción de antígenos D","RESPUESTA_CORRECTA":"A","EXPLICACION":"La prostaciclina ayuda a evitar la formación de tapones sobre vasos intactos.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué es trombocitopenia?","OPCION_A":"Disminución de eritrocitos","OPCION_B":"Disminución de plaquetas","OPCION_C":"Aumento de neutrófilos","OPCION_D":"Aumento de albúmina","RESPUESTA_CORRECTA":"B","EXPLICACION":"Un número bajo de plaquetas compromete la formación del tapón hemostático.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué distingue al tapón plaquetario del coágulo estabilizado?","OPCION_A":"El tapón está formado exclusivamente por hemoglobina","OPCION_B":"El coágulo carece siempre de plaquetas","OPCION_C":"El coágulo incorpora una red de fibrina","OPCION_D":"El tapón solo puede formarse después de la fibrinólisis","RESPUESTA_CORRECTA":"C","EXPLICACION":"La hemostasia primaria forma un tapón que la fibrina refuerza en la hemostasia secundaria.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"730-734"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué factor inicia la vía extrínseca al quedar expuesto por lesión tisular?","OPCION_A":"Factor tisular","OPCION_B":"Ferritina","OPCION_C":"Albúmina","OPCION_D":"Hemoglobina","RESPUESTA_CORRECTA":"A","EXPLICACION":"El factor tisular se asocia con el factor VII e inicia la vía extrínseca.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿En qué factor convergen las vías intrínseca y extrínseca clásicas?","OPCION_A":"Factor I exclusivamente","OPCION_B":"Factor X","OPCION_C":"Factor XII exclusivamente","OPCION_D":"Factor XIII exclusivamente","RESPUESTA_CORRECTA":"B","EXPLICACION":"La activación de X inicia la vía común que conduce a generar trombina y fibrina.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué molécula es precursora de la trombina?","OPCION_A":"Plasmina","OPCION_B":"Albúmina","OPCION_C":"Protrombina","OPCION_D":"Transferrina","RESPUESTA_CORRECTA":"C","EXPLICACION":"La protrombina es el factor II y se convierte en trombina durante la vía común.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué enzima convierte fibrinógeno en fibrina?","OPCION_A":"Plasmina","OPCION_B":"Amilasa","OPCION_C":"Eritropoyetina","OPCION_D":"Trombina","RESPUESTA_CORRECTA":"D","EXPLICACION":"La trombina genera fibrina a partir del fibrinógeno soluble.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué factor estabiliza la fibrina mediante entrecruzamiento?","OPCION_A":"Factor XIII","OPCION_B":"Factor VII","OPCION_C":"Factor XII","OPCION_D":"Factor II inactivo","RESPUESTA_CORRECTA":"A","EXPLICACION":"El factor XIII activado consolida los enlaces entre las fibras de fibrina.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué ion participa como cofactor en varias reacciones de coagulación?","OPCION_A":"Hierro","OPCION_B":"Calcio","OPCION_C":"Yodo","OPCION_D":"Zinc exclusivamente","RESPUESTA_CORRECTA":"B","EXPLICACION":"El calcio facilita el ensamblaje y funcionamiento de varios complejos de coagulación.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué vitamina es necesaria para la producción funcional de varios factores de coagulación?","OPCION_A":"Vitamina C","OPCION_B":"Vitamina A","OPCION_C":"Vitamina K","OPCION_D":"Vitamina B1","RESPUESTA_CORRECTA":"C","EXPLICACION":"La vitamina K interviene en modificaciones que permiten el funcionamiento de factores como II, VII, IX y X.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Por qué una alteración importante de síntesis hepática puede afectar la coagulación?","OPCION_A":"El hígado produce todas las plaquetas maduras por fragmentación","OPCION_B":"El hígado convierte todos los neutrófilos en fibrina","OPCION_C":"La bilis es la principal red de todo coágulo","OPCION_D":"El hígado produce numerosos factores plasmáticos","RESPUESTA_CORRECTA":"D","EXPLICACION":"Una menor síntesis de factores puede comprometer la hemostasia secundaria.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"732-736"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué mecanismo acerca los bordes de una lesión al compactar el coágulo?","OPCION_A":"Aglutinación ABO","OPCION_B":"Retracción del coágulo","OPCION_C":"Eritropoyesis","OPCION_D":"Hemólisis","RESPUESTA_CORRECTA":"B","EXPLICACION":"La contracción plaquetaria transmite fuerza a la red de fibrina y reduce el tamaño del coágulo.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué enzima degrada la fibrina durante la fibrinólisis?","OPCION_A":"Trombina","OPCION_B":"Renina","OPCION_C":"Plasmina","OPCION_D":"Ferritina","RESPUESTA_CORRECTA":"C","EXPLICACION":"La plasmina rompe la red de fibrina, mientras la trombina participa en su formación.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Cuál es el precursor inactivo de la plasmina?","OPCION_A":"Protrombina","OPCION_B":"Fibrinógeno","OPCION_C":"Hemocitoblasto","OPCION_D":"Plasminógeno","RESPUESTA_CORRECTA":"D","EXPLICACION":"El plasminógeno circulante se activa a plasmina durante la fibrinólisis.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué acción reguladora cumple la antitrombina?","OPCION_A":"Inhibe trombina y otros factores activados","OPCION_B":"Convierte hemoglobina en bilirrubina","OPCION_C":"Incrementa directamente el número de eritrocitos","OPCION_D":"Agrega antígeno D a los eritrocitos","RESPUESTA_CORRECTA":"A","EXPLICACION":"La antitrombina contribuye a limitar la coagulación y evitar su propagación innecesaria.","DIFICULTAD":"facil","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué diferencia un trombo de un émbolo?","OPCION_A":"Todo trombo es una proteína soluble y todo émbolo es un leucocito","OPCION_B":"El trombo se forma en un vaso y el émbolo circula por la sangre","OPCION_C":"El trombo solo aparece fuera del sistema circulatorio","OPCION_D":"Ambos términos significan exclusivamente hemorragia","RESPUESTA_CORRECTA":"B","EXPLICACION":"Un fragmento desprendido de un trombo puede viajar como tromboémbolo y obstruir otro vaso.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué deficiencia se asocia con hemofilia A?","OPCION_A":"Factor IX","OPCION_B":"Albúmina","OPCION_C":"Factor VIII","OPCION_D":"Transferrina","RESPUESTA_CORRECTA":"C","EXPLICACION":"La hemofilia A corresponde a una deficiencia funcional del factor VIII.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué deficiencia se asocia con hemofilia B?","OPCION_A":"Factor VIII","OPCION_B":"Hemoglobina fetal","OPCION_C":"Vitamina B12 exclusivamente","OPCION_D":"Factor IX","RESPUESTA_CORRECTA":"D","EXPLICACION":"La hemofilia B implica al factor IX; no debe confundirse con hemofilia A.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"},{"MATERIA":"MORFOFUNCION","TEMA":"sangre","PREGUNTA":"¿Qué diferencia general existe entre un defecto plaquetario y una deficiencia de factores de coagulación?","OPCION_A":"Afectan principalmente hemostasia primaria y secundaria, respectivamente","OPCION_B":"Ambos disminuyen exclusivamente el hematócrito","OPCION_C":"El defecto plaquetario impide únicamente degradar bilirrubina","OPCION_D":"La deficiencia de factores impide formar todos los leucocitos","RESPUESTA_CORRECTA":"A","EXPLICACION":"Las plaquetas forman el tapón inicial y los factores permiten estabilizarlo con fibrina, aunque ambos procesos interactúan.","DIFICULTAD":"medio","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","PAGINAS_PDF":"734-738"}]'::jsonb) AS p("MATERIA" text,"TEMA" text,"PREGUNTA" text,"OPCION_A" text,"OPCION_B" text,"OPCION_C" text,"OPCION_D" text,"RESPUESTA_CORRECTA" text,"EXPLICACION" text,"DIFICULTAD" text,"FUENTE" text,"PAGINAS_PDF" text);
WITH missing AS (SELECT p.* FROM morfo_incoming p WHERE NOT EXISTS (SELECT 1 FROM public.flashcards f WHERE lower(btrim(f.materia))=lower(btrim(p."MATERIA")) AND lower(btrim(f.tema))=lower(btrim(p."TEMA")) AND lower(btrim(f.pregunta))=lower(btrim(p."PREGUNTA")))), numbered AS (SELECT (SELECT coalesce(max(id),0) FROM public.flashcards)+row_number() over(order by "PREGUNTA") id,m.* FROM missing m)
INSERT INTO public.flashcards(id,materia,tema,pregunta,respuesta) SELECT id,"MATERIA","TEMA","PREGUNTA",CASE "RESPUESTA_CORRECTA" WHEN 'A' THEN "OPCION_A" WHEN 'B' THEN "OPCION_B" WHEN 'C' THEN "OPCION_C" ELSE "OPCION_D" END||'. '||"EXPLICACION" FROM numbered;
WITH missing AS (SELECT p.* FROM morfo_incoming p WHERE NOT EXISTS(SELECT 1 FROM public.banco_preguntas b WHERE lower(btrim(b."MATERIA"))=lower(btrim(p."MATERIA")) AND lower(btrim(b."TEMA"))=lower(btrim(p."TEMA")) AND lower(btrim(b."PREGUNTA"))=lower(btrim(p."PREGUNTA")))), numbered AS (SELECT (SELECT coalesce(max(id),0) FROM public.banco_preguntas)+row_number() over(order by "PREGUNTA") id,m.* FROM missing m)
INSERT INTO public.banco_preguntas(id,"MATERIA","TEMA","PREGUNTA","OPCION_A","OPCION_B","OPCION_C","OPCION_D","RESPUESTA_CORRECTA","EXPLICACION","DIFICULTAD","FUENTE","PAGINAS_PDF") SELECT id,"MATERIA","TEMA","PREGUNTA","OPCION_A","OPCION_B","OPCION_C","OPCION_D","RESPUESTA_CORRECTA","EXPLICACION","DIFICULTAD","FUENTE","PAGINAS_PDF" FROM numbered;
INSERT INTO public.simulacros(nombre,materia,tema,numero_pregunta,pregunta,opcion_a,opcion_b,opcion_c,opcion_d,respuesta_correcta,justificacion,dificultad,fuente,paginas_pdf)
SELECT p.nombre,p.materia,p.tema,p.numero_pregunta,p.pregunta,p.opcion_a,p.opcion_b,p.opcion_c,p.opcion_d,p.respuesta_correcta,p.justificacion,p.dificultad,p.fuente,p.paginas_pdf FROM jsonb_to_recordset('[{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":1,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué tipo de tejido es la sangre?","opcion_a":"Conjuntivo líquido","opcion_b":"Epitelial de revestimiento","opcion_c":"Muscular liso","opcion_d":"Nervioso periférico","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"707-711","justificacion":"Sus células y fragmentos celulares están suspendidos en una matriz extracelular líquida: el plasma."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":2,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es la matriz extracelular de la sangre?","opcion_a":"Hemoglobina","opcion_b":"Plasma","opcion_c":"Médula ósea roja","opcion_d":"Capa leucoplaquetaria","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"707-711","justificacion":"El plasma rodea los elementos formes y transporta solutos y proteínas."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":3,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué conjunto contiene únicamente elementos formes de la sangre?","opcion_a":"Albúmina, globulinas y fibrinógeno","opcion_b":"Agua, sodio y glucosa","opcion_c":"Eritrocitos, leucocitos y plaquetas","opcion_d":"Bilirrubina, urea y hormonas","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"707-711","justificacion":"Los elementos formes son cuerpos delimitados por membrana; las proteínas y solutos pertenecen al plasma."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":4,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál de los elementos formes es un fragmento celular?","opcion_a":"Monocito","opcion_b":"Eosinófilo","opcion_c":"Linfocito","opcion_d":"Plaqueta","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"707-711","justificacion":"Las plaquetas son fragmentos del citoplasma de megacariocitos, no células completas con núcleo."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":5,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es la proteína plasmática más abundante?","opcion_a":"Fibrinógeno","opcion_b":"Albúmina","opcion_c":"Hemoglobina","opcion_d":"Mioglobina","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"709-712","justificacion":"La albúmina es la principal proteína del plasma por abundancia y contribuye a transporte y presión oncótica."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":6,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué consecuencia favorece una disminución marcada de albúmina plasmática?","opcion_a":"Mayor síntesis de hemoglobina fetal","opcion_b":"Aumento obligatorio del número de plaquetas","opcion_c":"Edema por reducción de la presión oncótica","opcion_d":"Desaparición de los antígenos ABO","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"709-712","justificacion":"Al disminuir la fuerza oncótica que retiene agua en los vasos, se favorece su acumulación intersticial."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":7,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué proteína soluble se convierte en la red insoluble que estabiliza el coágulo?","opcion_a":"Albúmina","opcion_b":"Transferrina","opcion_c":"Ferritina","opcion_d":"Fibrinógeno","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"709-712","justificacion":"La trombina transforma el fibrinógeno en fibrina durante la coagulación."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":8,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué fracción proteica incluye a los anticuerpos circulantes?","opcion_a":"Inmunoglobulinas","opcion_b":"Hemoglobinas","opcion_c":"Apoferritinas","opcion_d":"Fibrinas","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"709-712","justificacion":"Las inmunoglobulinas participan en la defensa específica y son producidas por células plasmáticas."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":9,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es el principal sitio de hematopoyesis en el adulto?","opcion_a":"Médula espinal","opcion_b":"Cartílago articular","opcion_c":"Médula ósea roja","opcion_d":"Corteza cerebral","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"711-716","justificacion":"La médula ósea roja contiene las células madre y el entorno de maduración de las células sanguíneas."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":10,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué célula origina las distintas líneas de elementos formes?","opcion_a":"Eritrocito maduro","opcion_b":"Plaqueta circulante","opcion_c":"Fibroblasto dérmico","opcion_d":"Célula madre hematopoyética","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"711-716","justificacion":"La célula madre hematopoyética puede autorrenovarse y originar linajes sanguíneos especializados."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":11,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué proceso produce eritrocitos?","opcion_a":"Eritropoyesis","opcion_b":"Leucopoyesis","opcion_c":"Trombopoyesis","opcion_d":"Fibrinólisis","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"711-716","justificacion":"La eritropoyesis es la producción y maduración de la línea eritroide."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":12,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué hormona estimula de manera directa la producción eritroide ante hipoxia?","opcion_a":"Trombopoyetina","opcion_b":"Eritropoyetina","opcion_c":"Calcitonina","opcion_d":"Aldosterona","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"711-716","justificacion":"La eritropoyetina actúa sobre precursores eritroides de la médula ósea."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":13,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es la forma habitual de un eritrocito humano maduro?","opcion_a":"Esfera con núcleo multilobulado","opcion_b":"Cilindro ciliado","opcion_c":"Célula estrellada con dendritas","opcion_d":"Disco bicóncavo","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"712-716","justificacion":"La forma bicóncava y la flexibilidad favorecen el intercambio y el paso por vasos pequeños."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":14,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué organelos faltan en el eritrocito humano maduro?","opcion_a":"Núcleo y mitocondrias","opcion_b":"Solo lisosomas, con núcleo conservado","opcion_c":"Solo ribosomas, con mitocondrias abundantes","opcion_d":"Solo aparato de Golgi, con núcleo conservado","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"712-716","justificacion":"El eritrocito maduro pierde núcleo y organelos, y obtiene energía principalmente mediante glucólisis."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":15,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué componente de la hemoglobina une directamente el oxígeno?","opcion_a":"Cadena de albúmina plasmática","opcion_b":"Hierro ferroso del grupo hemo","opcion_c":"Calcio de la membrana eritrocitaria","opcion_d":"Bilirrubina del citoplasma","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"712-716","justificacion":"Cada grupo hemo posee un ion Fe2+ capaz de unir una molécula de oxígeno."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":16,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuántas moléculas de oxígeno puede unir una molécula de hemoglobina completamente saturada?","opcion_a":"Una","opcion_b":"Dos","opcion_c":"Cuatro","opcion_d":"Ocho","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"712-716","justificacion":"La hemoglobina contiene cuatro grupos hemo, cada uno con capacidad para una molécula de oxígeno."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":17,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es la vida media aproximada del eritrocito humano?","opcion_a":"120 días","opcion_b":"24 horas","opcion_c":"7 días","opcion_d":"10 años","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"715-720","justificacion":"El envejecimiento de la membrana limita su supervivencia a unos cuatro meses."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":18,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué células eliminan muchos eritrocitos envejecidos?","opcion_a":"Eosinófilos exclusivamente","opcion_b":"Macrófagos","opcion_c":"Megacariocitos","opcion_d":"Osteoblastos","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"715-720","justificacion":"Los macrófagos esplénicos, hepáticos y medulares reciclan componentes de los eritrocitos."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":19,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué proteína transporta hierro por el plasma?","opcion_a":"Ferritina","opcion_b":"Fibrina","opcion_c":"Transferrina","opcion_d":"Rodopsina","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"715-720","justificacion":"La transferrina lleva hierro circulante hacia tejidos que lo utilizan o almacenan."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":20,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué proteína almacena hierro dentro de las células?","opcion_a":"Transferrina","opcion_b":"Protrombina","opcion_c":"Albúmina","opcion_d":"Ferritina","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"715-720","justificacion":"La ferritina permite almacenar hierro; su función se diferencia del transporte plasmático por transferrina."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":21,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué determina el grupo ABO de un eritrocito?","opcion_a":"Cantidad de hemoglobina fetal","opcion_b":"Presencia o ausencia de antígenos A y B","opcion_c":"Número de mitocondrias del eritrocito","opcion_d":"Concentración plasmática de albúmina","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"719-723","justificacion":"Los antígenos A y B de la membrana eritrocitaria definen los grupos ABO."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":22,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué combinación corresponde al grupo A?","opcion_a":"Antígeno B y anticuerpos anti-A habituales","opcion_b":"Antígenos A y B con anti-A y anti-B habituales","opcion_c":"Antígeno A y anticuerpos anti-B habituales","opcion_d":"Ausencia de A y B sin anticuerpos habituales","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"719-723","justificacion":"El plasma del grupo A presenta normalmente anti-B, no anti-A contra sus propios eritrocitos."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":23,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué combinación corresponde al grupo B?","opcion_a":"Antígeno A y anticuerpos anti-B habituales","opcion_b":"Antígenos A y B sin antígenos Rh posibles","opcion_c":"Ausencia de A y B con antígeno A soluble","opcion_d":"Antígeno B y anticuerpos anti-A habituales","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"719-723","justificacion":"La expresión del antígeno B se acompaña habitualmente de anticuerpos contra A."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":24,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué caracteriza al grupo AB en el sistema ABO?","opcion_a":"Antígenos A y B y ausencia habitual de anti-A y anti-B","opcion_b":"Solo antígeno A y presencia de anti-B","opcion_c":"Ausencia de ambos antígenos y presencia de ambos anticuerpos","opcion_d":"Solo antígeno B y presencia de anti-A","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"719-723","justificacion":"El sistema inmunitario no genera normalmente anticuerpos ABO contra los antígenos propios A y B."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":25,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es un granulocito?","opcion_a":"Monocito","opcion_b":"Linfocito B","opcion_c":"Neutrófilo","opcion_d":"Linfocito T","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"724-730","justificacion":"Neutrófilos, eosinófilos y basófilos constituyen los granulocitos."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":26,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué pareja está formada por agranulocitos?","opcion_a":"Neutrófilos y eosinófilos","opcion_b":"Basófilos y neutrófilos","opcion_c":"Eritrocitos y plaquetas","opcion_d":"Linfocitos y monocitos","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"724-730","justificacion":"La clasificación distingue linfocitos y monocitos de los tres tipos de granulocitos."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":27,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué leucocito tiene un papel destacado en la fagocitosis de bacterias?","opcion_a":"Neutrófilo","opcion_b":"Basófilo","opcion_c":"Linfocito B inactivo","opcion_d":"Eritrocito","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"724-730","justificacion":"Los neutrófilos son abundantes y participan de forma importante en la respuesta antibacteriana temprana."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":28,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué leucocito se vincula especialmente con defensa contra parásitos y reacciones alérgicas?","opcion_a":"Eritrocito","opcion_b":"Eosinófilo","opcion_c":"Megacariocito","opcion_d":"Reticulocito","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"724-730","justificacion":"Los eosinófilos liberan productos granulares y participan en estas respuestas; la asociación no es exclusiva."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":29,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿De qué célula proceden las plaquetas?","opcion_a":"Eritroblasto","opcion_b":"Monoblasto","opcion_c":"Fibroblasto","opcion_d":"Megacariocito","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"730-734","justificacion":"Los megacariocitos liberan fragmentos citoplasmáticos que se convierten en plaquetas."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":30,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué proceso limita la pérdida de sangre tras lesión vascular?","opcion_a":"Hemostasia","opcion_b":"Hematopoyesis","opcion_c":"Hemólisis","opcion_d":"Hemodilución","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"730-734","justificacion":"La hemostasia integra respuestas vasculares, plaquetarias y de coagulación."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":31,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es la secuencia general de los mecanismos hemostáticos?","opcion_a":"Fibrinólisis, eritropoyesis y hemólisis","opcion_b":"Espasmo vascular, tapón plaquetario y coagulación","opcion_c":"Coagulación, síntesis de albúmina y leucopoyesis","opcion_d":"Hemólisis, aglutinación y secreción de bilis","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"730-734","justificacion":"La vasoconstricción y el tapón temprano limitan la pérdida; la fibrina estabiliza después el cierre."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":32,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué cambio de la pared lesionada facilita la adhesión de plaquetas?","opcion_a":"Aumento de la capa intacta de prostaciclina","opcion_b":"Desaparición de toda matriz extracelular","opcion_c":"Exposición del colágeno subendotelial","opcion_d":"Formación de eritrocitos nucleados","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"730-734","justificacion":"La lesión expone superficies que activan mecanismos de adhesión plaquetaria."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":33,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué factor inicia la vía extrínseca al quedar expuesto por lesión tisular?","opcion_a":"Factor tisular","opcion_b":"Ferritina","opcion_c":"Albúmina","opcion_d":"Hemoglobina","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"732-736","justificacion":"El factor tisular se asocia con el factor VII e inicia la vía extrínseca."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":34,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿En qué factor convergen las vías intrínseca y extrínseca clásicas?","opcion_a":"Factor I exclusivamente","opcion_b":"Factor X","opcion_c":"Factor XII exclusivamente","opcion_d":"Factor XIII exclusivamente","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"732-736","justificacion":"La activación de X inicia la vía común que conduce a generar trombina y fibrina."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":35,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué molécula es precursora de la trombina?","opcion_a":"Plasmina","opcion_b":"Albúmina","opcion_c":"Protrombina","opcion_d":"Transferrina","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"732-736","justificacion":"La protrombina es el factor II y se convierte en trombina durante la vía común."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":36,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué enzima convierte fibrinógeno en fibrina?","opcion_a":"Plasmina","opcion_b":"Amilasa","opcion_c":"Eritropoyetina","opcion_d":"Trombina","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"732-736","justificacion":"La trombina genera fibrina a partir del fibrinógeno soluble."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":37,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué mecanismo acerca los bordes de una lesión al compactar el coágulo?","opcion_a":"Aglutinación ABO","opcion_b":"Retracción del coágulo","opcion_c":"Eritropoyesis","opcion_d":"Hemólisis","respuesta_correcta":"B","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"734-738","justificacion":"La contracción plaquetaria transmite fuerza a la red de fibrina y reduce el tamaño del coágulo."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":38,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué enzima degrada la fibrina durante la fibrinólisis?","opcion_a":"Trombina","opcion_b":"Renina","opcion_c":"Plasmina","opcion_d":"Ferritina","respuesta_correcta":"C","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"734-738","justificacion":"La plasmina rompe la red de fibrina, mientras la trombina participa en su formación."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":39,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Cuál es el precursor inactivo de la plasmina?","opcion_a":"Protrombina","opcion_b":"Fibrinógeno","opcion_c":"Hemocitoblasto","opcion_d":"Plasminógeno","respuesta_correcta":"D","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"734-738","justificacion":"El plasminógeno circulante se activa a plasmina durante la fibrinólisis."},{"nombre":"Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)","numero_pregunta":40,"materia":"MORFOFUNCION","tema":"sangre","pregunta":"¿Qué acción reguladora cumple la antitrombina?","opcion_a":"Inhibe trombina y otros factores activados","opcion_b":"Convierte hemoglobina en bilirrubina","opcion_c":"Incrementa directamente el número de eritrocitos","opcion_d":"Agrega antígeno D a los eritrocitos","respuesta_correcta":"A","dificultad":"facil","fuente":"Saladin, Anatomía y fisiología: la unidad entre forma y función, capítulo 18","paginas_pdf":"734-738","justificacion":"La antitrombina contribuye a limitar la coagulación y evitar su propagación innecesaria."}]'::jsonb) AS p(nombre text,materia text,tema text,numero_pregunta int,pregunta text,opcion_a text,opcion_b text,opcion_c text,opcion_d text,respuesta_correcta text,justificacion text,dificultad text,fuente text,paginas_pdf text) WHERE NOT EXISTS(SELECT 1 FROM public.simulacros s WHERE s.nombre=p.nombre AND s.numero_pregunta=p.numero_pregunta);
INSERT INTO public.evaluaciones(id,titulo,asignatura,tema,nivel,idioma,visibilidad,objetivo,codigo,publicado,iniciado,modo_sesion,config_juego)
