INSERT INTO public.evaluacion_preguntas(id,evaluacion_id,tipo,texto,opciones,orden,puntos,temporizador)
SELECT p.id,p.evaluacion_id,p.tipo,p.texto,p.opciones,p.orden,p.puntos,p.temporizador FROM jsonb_to_recordset('[{"id":"a4f5929c-f3f6-5699-a525-e70d9323c295","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué representa el hematócrito?","opciones":[{"text":"Porcentaje del volumen sanguíneo ocupado por eritrocitos","correct":true,"color":"ac-blue"},{"text":"Número de leucocitos por microlitro","correct":false,"color":"ac-pink"},{"text":"Masa de hemoglobina en un eritrocito","correct":false,"color":"ac-yellow"},{"text":"Porcentaje de proteínas del plasma","correct":false,"color":"ac-green"}],"orden":1,"puntos":1,"temporizador":60},{"id":"abc43d6c-58d9-5e5a-818f-65ec7537edcb","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué contiene principalmente la capa leucoplaquetaria de sangre centrifugada?","opciones":[{"text":"Eritrocitos y hemoglobina libre","correct":false,"color":"ac-blue"},{"text":"Leucocitos y plaquetas","correct":true,"color":"ac-pink"},{"text":"Albúmina y agua exclusivamente","correct":false,"color":"ac-yellow"},{"text":"Fibrina y bilirrubina exclusivamente","correct":false,"color":"ac-green"}],"orden":2,"puntos":1,"temporizador":60},{"id":"dea84948-10c5-5dd2-b1ea-f3aace5721cd","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Cuál es una función reguladora de la sangre?","opciones":[{"text":"Producir bilis en los eritrocitos","correct":false,"color":"ac-blue"},{"text":"Sintetizar insulina en los leucocitos","correct":false,"color":"ac-pink"},{"text":"Distribuir calor y contribuir al equilibrio del pH","correct":true,"color":"ac-yellow"},{"text":"Filtrar la orina en las plaquetas","correct":false,"color":"ac-green"}],"orden":3,"puntos":1,"temporizador":60},{"id":"29bc840a-bc56-5c19-a2b0-58cac9c4b5ec","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Cómo se obtiene el suero a partir de una muestra de sangre?","opciones":[{"text":"Añadiendo eritrocitos al plasma","correct":false,"color":"ac-blue"},{"text":"Dejando coagular y separando el coágulo","correct":true,"color":"ac-pink"},{"text":"Retirando solo los leucocitos de sangre anticoagulada","correct":false,"color":"ac-yellow"},{"text":"Diluyendo el plasma con agua hasta la mitad","correct":false,"color":"ac-green"}],"orden":4,"puntos":1,"temporizador":60},{"id":"1eb63ea6-4964-5f0f-adda-156236f45e5c","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué órgano sintetiza la mayor parte de las proteínas plasmáticas?","opciones":[{"text":"Bazo","correct":false,"color":"ac-blue"},{"text":"Timo","correct":false,"color":"ac-pink"},{"text":"Hígado","correct":true,"color":"ac-yellow"},{"text":"Médula suprarrenal","correct":false,"color":"ac-green"}],"orden":5,"puntos":1,"temporizador":60},{"id":"c3fd94f3-8957-5c72-94cb-6e98fe5794e5","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué ion es el principal catión del plasma y contribuye de forma importante a su osmolaridad?","opciones":[{"text":"Hierro","correct":false,"color":"ac-blue"},{"text":"Cobre","correct":false,"color":"ac-pink"},{"text":"Zinc","correct":false,"color":"ac-yellow"},{"text":"Sodio","correct":true,"color":"ac-green"}],"orden":6,"puntos":1,"temporizador":60},{"id":"479a60c5-9c9f-5c8f-b211-4887cf352b61","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué órgano aporta la mayor parte de la eritropoyetina en el adulto?","opciones":[{"text":"Bazo","correct":false,"color":"ac-blue"},{"text":"Timo","correct":false,"color":"ac-pink"},{"text":"Riñón","correct":true,"color":"ac-yellow"},{"text":"Páncreas","correct":false,"color":"ac-green"}],"orden":7,"puntos":1,"temporizador":60},{"id":"8b53a4ab-5250-5463-ad9f-b67a4b563301","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué caracteriza al reticulocito?","opciones":[{"text":"Leucocito con núcleo multilobulado","correct":false,"color":"ac-blue"},{"text":"Megacariocito con núcleo fragmentado","correct":false,"color":"ac-pink"},{"text":"Eritrocito maduro con mitocondrias funcionales","correct":false,"color":"ac-yellow"},{"text":"Eritrocito inmaduro con restos de ARN","correct":true,"color":"ac-green"}],"orden":8,"puntos":1,"temporizador":60},{"id":"3245d180-1815-5f41-9bd6-58c52fa947b6","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué función comparten vitamina B12 y folato en la eritropoyesis?","opciones":[{"text":"Favorecer la síntesis de ADN de los precursores","correct":true,"color":"ac-blue"},{"text":"Formar directamente el ion ferroso del hemo","correct":false,"color":"ac-pink"},{"text":"Convertir fibrinógeno en fibrina","correct":false,"color":"ac-yellow"},{"text":"Destruir eritrocitos envejecidos","correct":false,"color":"ac-green"}],"orden":9,"puntos":1,"temporizador":60},{"id":"ebd8f30f-adce-5ac6-a656-61be2efd7468","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué cadenas constituyen la hemoglobina adulta predominante HbA?","opciones":[{"text":"Dos alfa y dos gamma","correct":false,"color":"ac-blue"},{"text":"Cuatro gamma","correct":false,"color":"ac-pink"},{"text":"Dos beta y dos delta","correct":false,"color":"ac-yellow"},{"text":"Dos alfa y dos beta","correct":true,"color":"ac-green"}],"orden":10,"puntos":1,"temporizador":60},{"id":"bec9edcf-30c0-59ff-a7b7-0e77bb9f6c61","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué distingue funcionalmente a la hemoglobina fetal de la HbA?","opciones":[{"text":"Mayor afinidad por el oxígeno","correct":true,"color":"ac-blue"},{"text":"Incapacidad para unir oxígeno","correct":false,"color":"ac-pink"},{"text":"Ausencia de grupos hemo","correct":false,"color":"ac-yellow"},{"text":"Presencia de hierro férrico como única forma funcional","correct":false,"color":"ac-green"}],"orden":11,"puntos":1,"temporizador":60},{"id":"92dd6ec5-49ce-5a20-bb2c-59db5d645c49","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Dónde puede unirse parte del dióxido de carbono transportado por hemoglobina?","opciones":[{"text":"En el sitio del hierro destinado al oxígeno","correct":false,"color":"ac-blue"},{"text":"En grupos de la globina","correct":true,"color":"ac-pink"},{"text":"Exclusivamente dentro de la ferritina","correct":false,"color":"ac-yellow"},{"text":"En las cadenas de fibrina","correct":false,"color":"ac-green"}],"orden":12,"puntos":1,"temporizador":60},{"id":"545d3766-d784-57e3-b412-4e5439a9aca1","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué pigmento se forma durante la degradación del hemo y puede acumularse en la ictericia?","opciones":[{"text":"Bilirrubina","correct":true,"color":"ac-blue"},{"text":"Melanina","correct":false,"color":"ac-pink"},{"text":"Rodopsina","correct":false,"color":"ac-yellow"},{"text":"Hemocianina","correct":false,"color":"ac-green"}],"orden":13,"puntos":1,"temporizador":60},{"id":"01893190-8f10-594f-89f9-34e2ca7e7af8","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué cambio define funcionalmente a la anemia?","opciones":[{"text":"Aumento obligatorio de plaquetas","correct":false,"color":"ac-blue"},{"text":"Disminución de la capacidad sanguínea de transportar oxígeno","correct":true,"color":"ac-pink"},{"text":"Exceso de todos los leucocitos","correct":false,"color":"ac-yellow"},{"text":"Aumento de la viscosidad por exceso eritrocitario","correct":false,"color":"ac-green"}],"orden":14,"puntos":1,"temporizador":60},{"id":"cc7422ad-0e7e-5028-9965-d736f160d4e4","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué alteración puede aumentar la viscosidad sanguínea por exceso eritrocitario?","opciones":[{"text":"Trombocitopenia","correct":false,"color":"ac-blue"},{"text":"Leucopenia","correct":false,"color":"ac-pink"},{"text":"Policitemia","correct":true,"color":"ac-yellow"},{"text":"Hemofilia","correct":false,"color":"ac-green"}],"orden":15,"puntos":1,"temporizador":60},{"id":"f203faf1-03bc-5177-8240-e3aa93053c98","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué caracteriza a los eritrocitos del grupo O en el sistema ABO?","opciones":[{"text":"No presentan ninguna molécula antigénica de ningún sistema","correct":false,"color":"ac-blue"},{"text":"No presentan antígenos A ni B","correct":true,"color":"ac-pink"},{"text":"Presentan ambos antígenos A y B","correct":false,"color":"ac-yellow"},{"text":"Presentan antígeno A solo durante la infancia","correct":false,"color":"ac-green"}],"orden":16,"puntos":1,"temporizador":60},{"id":"72a84a28-8e53-58b9-9eaf-90f415e724a0","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Cómo se llama la unión de eritrocitos en grupos mediada por anticuerpos?","opciones":[{"text":"Eritropoyesis","correct":false,"color":"ac-blue"},{"text":"Fibrinólisis","correct":false,"color":"ac-pink"},{"text":"Aglutinación","correct":true,"color":"ac-yellow"},{"text":"Quimiotaxis","correct":false,"color":"ac-green"}],"orden":17,"puntos":1,"temporizador":60},{"id":"d9d4435d-ef92-5611-9474-afe11fcf7934","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué define habitualmente a una persona Rh positiva?","opciones":[{"text":"Presencia obligatoria de anti-D desde el nacimiento","correct":false,"color":"ac-blue"},{"text":"Ausencia de todos los antígenos eritrocitarios","correct":false,"color":"ac-pink"},{"text":"Pertenencia exclusiva al grupo AB","correct":false,"color":"ac-yellow"},{"text":"Presencia del antígeno D eritrocitario","correct":true,"color":"ac-green"}],"orden":18,"puntos":1,"temporizador":60},{"id":"f715cd4e-cb6a-50cc-bf66-64c73f0f00c4","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué leucocito circulante puede diferenciarse en macrófago tisular?","opciones":[{"text":"Basófilo","correct":false,"color":"ac-blue"},{"text":"Eritrocito","correct":false,"color":"ac-pink"},{"text":"Monocito","correct":true,"color":"ac-yellow"},{"text":"Plaqueta","correct":false,"color":"ac-green"}],"orden":19,"puntos":1,"temporizador":60},{"id":"fb16b1b1-5959-5800-b636-2d696e26323e","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué células originan las células plasmáticas productoras de anticuerpos?","opciones":[{"text":"Neutrófilos","correct":false,"color":"ac-blue"},{"text":"Eosinófilos","correct":false,"color":"ac-pink"},{"text":"Megacariocitos","correct":false,"color":"ac-yellow"},{"text":"Linfocitos B","correct":true,"color":"ac-green"}],"orden":20,"puntos":1,"temporizador":60},{"id":"73bf69e0-372d-5784-8671-1d285b42b6f5","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué significa diapédesis leucocitaria?","opciones":[{"text":"Paso del leucocito a través de la pared vascular","correct":true,"color":"ac-blue"},{"text":"División de un eritrocito maduro","correct":false,"color":"ac-pink"},{"text":"Conversión de fibrinógeno en fibrina","correct":false,"color":"ac-yellow"},{"text":"Unión del hierro a transferrina","correct":false,"color":"ac-green"}],"orden":21,"puntos":1,"temporizador":60},{"id":"082b1b64-7176-5b2f-9174-f0eb4aac6f32","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué sustancia liberada por plaquetas ayuda a reclutar más plaquetas?","opciones":[{"text":"Bilirrubina","correct":false,"color":"ac-blue"},{"text":"Ferritina","correct":false,"color":"ac-pink"},{"text":"Eritropoyetina","correct":false,"color":"ac-yellow"},{"text":"ADP","correct":true,"color":"ac-green"}],"orden":22,"puntos":1,"temporizador":60},{"id":"322089d6-046a-5387-bd90-ee11a4bf2e34","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué efecto tiene la prostaciclina del endotelio sano sobre las plaquetas?","opciones":[{"text":"Dificulta su activación y agregación","correct":true,"color":"ac-blue"},{"text":"Convierte plaquetas en megacariocitos","correct":false,"color":"ac-pink"},{"text":"Transforma directamente fibrinógeno en fibrina","correct":false,"color":"ac-yellow"},{"text":"Estimula la producción de antígenos D","correct":false,"color":"ac-green"}],"orden":23,"puntos":1,"temporizador":60},{"id":"d4919bb8-ba79-593f-8d51-56bc7e12ac43","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué es trombocitopenia?","opciones":[{"text":"Disminución de eritrocitos","correct":false,"color":"ac-blue"},{"text":"Disminución de plaquetas","correct":true,"color":"ac-pink"},{"text":"Aumento de neutrófilos","correct":false,"color":"ac-yellow"},{"text":"Aumento de albúmina","correct":false,"color":"ac-green"}],"orden":24,"puntos":1,"temporizador":60},{"id":"c110fc12-7926-5375-bc01-9142f12c4c4d","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué factor estabiliza la fibrina mediante entrecruzamiento?","opciones":[{"text":"Factor XIII","correct":true,"color":"ac-blue"},{"text":"Factor VII","correct":false,"color":"ac-pink"},{"text":"Factor XII","correct":false,"color":"ac-yellow"},{"text":"Factor II inactivo","correct":false,"color":"ac-green"}],"orden":25,"puntos":1,"temporizador":60},{"id":"611e4d4f-9411-52d5-a07a-8b1d4b06998e","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué ion participa como cofactor en varias reacciones de coagulación?","opciones":[{"text":"Hierro","correct":false,"color":"ac-blue"},{"text":"Calcio","correct":true,"color":"ac-pink"},{"text":"Yodo","correct":false,"color":"ac-yellow"},{"text":"Zinc exclusivamente","correct":false,"color":"ac-green"}],"orden":26,"puntos":1,"temporizador":60},{"id":"7c58dd77-c11d-5525-9b59-3e51790d90ca","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué vitamina es necesaria para la producción funcional de varios factores de coagulación?","opciones":[{"text":"Vitamina C","correct":false,"color":"ac-blue"},{"text":"Vitamina A","correct":false,"color":"ac-pink"},{"text":"Vitamina K","correct":true,"color":"ac-yellow"},{"text":"Vitamina B1","correct":false,"color":"ac-green"}],"orden":27,"puntos":1,"temporizador":60},{"id":"a175dd7b-74c8-5379-b330-3c9842444465","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué diferencia un trombo de un émbolo?","opciones":[{"text":"Todo trombo es una proteína soluble y todo émbolo es un leucocito","correct":false,"color":"ac-blue"},{"text":"El trombo se forma en un vaso y el émbolo circula por la sangre","correct":true,"color":"ac-pink"},{"text":"El trombo solo aparece fuera del sistema circulatorio","correct":false,"color":"ac-yellow"},{"text":"Ambos términos significan exclusivamente hemorragia","correct":false,"color":"ac-green"}],"orden":28,"puntos":1,"temporizador":60},{"id":"c4d0cfc1-50f8-5ddd-96d4-a2e681e01e0b","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué deficiencia se asocia con hemofilia A?","opciones":[{"text":"Factor IX","correct":false,"color":"ac-blue"},{"text":"Albúmina","correct":false,"color":"ac-pink"},{"text":"Factor VIII","correct":true,"color":"ac-yellow"},{"text":"Transferrina","correct":false,"color":"ac-green"}],"orden":29,"puntos":1,"temporizador":60},{"id":"5a317121-d391-5167-945a-631fb04d3751","evaluacion_id":"936dd987-1f00-5ae5-beeb-d2edb94f2e8e","tipo":"mc","texto":"¿Qué deficiencia se asocia con hemofilia B?","opciones":[{"text":"Factor VIII","correct":false,"color":"ac-blue"},{"text":"Hemoglobina fetal","correct":false,"color":"ac-pink"},{"text":"Vitamina B12 exclusivamente","correct":false,"color":"ac-yellow"},{"text":"Factor IX","correct":true,"color":"ac-green"}],"orden":30,"puntos":1,"temporizador":60}]'::jsonb) AS p(id uuid,evaluacion_id uuid,tipo text,texto text,opciones jsonb,orden int,puntos int,temporizador int) ON CONFLICT(id) DO NOTHING;
COMMIT;
SELECT 'flashcards' recurso,count(*) cantidad FROM public.flashcards WHERE materia='MORFOFUNCION' AND tema='sangre' UNION ALL SELECT 'banco',count(*) FROM public.banco_preguntas WHERE "MATERIA"='MORFOFUNCION' AND "TEMA"='sangre' UNION ALL SELECT 'simulacro',count(*) FROM public.simulacros WHERE nombre='Práctica bibliográfica - Morfofunción - Sangre (40 preguntas)' UNION ALL SELECT 'evaluacion',count(*) FROM public.evaluacion_preguntas WHERE evaluacion_id='936dd987-1f00-5ae5-beeb-d2edb94f2e8e'::uuid;
